 <style>
 .labeled-input {
  position: relative;
  margin-top: 15px;
}

.labeled-input input {
  width: 100%;
  padding: 12px 10px;
  border: 1px solid #ccc;
  border-radius: 4px;
  font-size: 16px;
  outline: none;
}

/* Position label over the input */
.labeled-input label {
  position: absolute;
  left: 10px;
  top: 50%;
  transform: translateY(-50%);
  background-color: white;
  padding: 0 4px;
  color: #888;
  transition: 0.2s ease all;
  pointer-events: none; /* Allows clicks to pass through to input */
}

/* Move label up when focused OR when text has been typed */
.labeled-input input:focus + label,
.labeled-input input:not(:placeholder-shown) + label {
  top: 0;
  font-size: 12px;
  color: #007bff;
}
</style>
