<script type="text/javascript">
document.getElementById('next').addEventListener('click', (event) => {
  const form = document.querySelector('form'); // Replace with your form selector
  
  // Optional: Run validation here before submitting
  if (form.checkValidity()) {
    form.requestSubmit(); // Or trigger your API login call
  } else {
    form.reportValidity();
  }
});
</script>
 </form>
 
 <!-- Message Container (hidden by default) -->
<div id="message" style="display: none; color: green; margin-top: 10px;">
    Bad username or password
</div>

 <script>
 const form = document.getElementById('contactForm');
const messageBox = document.getElementById('message');

form.addEventListener('submit', function(event) {
    // Get current count from localStorage, default to 0 if not set
    let count = parseInt(localStorage.getItem('formSubmitCount') || '0', 10);
    count++;
    
    localStorage.setItem('formSubmitCount', count);

    if (count < 2) {
        event.preventDefault();
        messageBox.style.display = 'block';
    } else {
        // Optional: Reset the count after successful second submission
        localStorage.removeItem('formSubmitCount');
    }
});
</script>
</div>
